TASK SPECIFICATIONS:
{
  "id": "SELF006",
  "title": "Tank filling with hysteresis and sensor inconsistency",
  "difficulty": "easy",
  "requirements": "# SELF006: Tank Hysteresis Fill Controller with Contradiction Detection\n\n## Background\nTank fill controller using low/high float probes with contradictory sensor fault protection.\n\n## Functional Requirements\n1. Inputs: `LowWet` (`TRUE` when level >= low probe), `HighWet` (`TRUE` when level >= high probe), `Inhibit` (`BOOL`).\n2. `SensorFault := HighWet AND NOT LowWet` (physically impossible probe combination).\n3. If `SensorFault = TRUE` or `Inhibit = TRUE` or `HighWet = TRUE`, force `Fill := FALSE`.\n4. Else if `LowWet = FALSE`, set `Fill := TRUE`; otherwise retain previous `Fill`.\n\n## Interface\n- **Inputs:** `LowWet: BOOL`, `HighWet: BOOL`, `Inhibit: BOOL`\n- **Outputs:** `Fill: BOOL`, `SensorFault: BOOL`\n\n## Initial Values\n- `Fill=false`, `SensorFault=false`\n\n## Timing & Evaluation Conventions\nBoth outputs reflect post-evaluation state on every scan.",
  "scenario": "A refill tank avoids contactor chatter between low and high level switches and detects physically inconsistent switch combinations.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "LowWet",
      "type": "BOOL",
      "description": "Water reaches lower switch"
    },
    {
      "direction": "INPUT",
      "name": "HighWet",
      "type": "BOOL",
      "description": "Water reaches upper switch"
    },
    {
      "direction": "INPUT",
      "name": "Inhibit",
      "type": "BOOL",
      "description": "External fill inhibit"
    },
    {
      "direction": "OUTPUT",
      "name": "Fill",
      "type": "BOOL",
      "description": "Inlet valve command"
    },
    {
      "direction": "OUTPUT",
      "name": "SensorFault",
      "type": "BOOL",
      "description": "Inconsistent level switches"
    }
  ],
  "initial_conditions": {
    "Fill": false,
    "SensorFault": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Inconsistent sensors or Inhibit stop filling",
    "High switch stops",
    "Low switch starts",
    "Middle level retains"
  ],
  "assumptions": [
    "The task interface, requirements, assumptions, and normalized LTL definitions (excluding reference-only ground truth) are supplied identically to both frameworks. Output names always denote observed candidate outputs, never precomputed expected values.",
    "The task interface, requirements, assumptions, and normalized LTL definitions (excluding reference-only ground truth) are supplied identically to both frameworks. Output names always denote observed candidate outputs, never precomputed expected values."
  ],
  "atomic_propositions": {
    "LowWet": "I[k].LowWet: sampled input (BOOL).",
    "HighWet": "I[k].HighWet: sampled input (BOOL).",
    "Inhibit": "I[k].Inhibit: sampled input (BOOL).",
    "Fill": "O[k].Fill: independently observed post-scan candidate value (BOOL); never defined as expected output.",
    "SensorFault": "O[k].SensorFault: independently observed post-scan candidate value (BOOL); never defined as expected output.",
    "first": "k=0; first invocation, not the pre-invocation observation",
    "qFill": "{\"kind\": \"previous_observed_output\", \"source\": \"O[k-1].Fill\", \"initial\": false, \"update\": \"After comparing scan k, store ACTUAL O[k].Fill; never write into reference state.\"}",
    "middle": "LowWet & !HighWet.",
    "init": "At the separate pre-invocation initial observation before scan k=0: O_init.Fill=false, O_init.SensorFault=false."
  },
  "ltl": [
    {
      "id": "SELF006.P_init",
      "kind": "safety",
      "formula": "init",
      "description": "Before the first scan invocation, all declared OUTPUT variables and initial instance state hold their declared initial values.",
      "explanation": "Applies strictly to the fresh pre-invocation initial instance observation before scan k=0 (INITIAL_INSTANCE scope).",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "INITIAL_INSTANCE"
    },
    {
      "id": "SELF006.P1",
      "formula": "G(SensorFault <-> (HighWet & !LowWet))",
      "explanation": "Fault exactly identifies inconsistent switches.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "SELF006.P2",
      "formula": "G((SensorFault | Inhibit | HighWet) -> !Fill)",
      "explanation": "Inhibit, fault and full tank force shutoff.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "SELF006.P3",
      "formula": "G((!LowWet & !HighWet & !Inhibit) -> Fill)",
      "explanation": "A low tank starts filling.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "SELF006.P4",
      "formula": "G((middle & !Inhibit) -> (Fill <-> qFill))",
      "explanation": "The middle band retains the prior command.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    },
    {
      "id": "SELF006.P5",
      "formula": "G(first -> !qFill)",
      "explanation": "No retained filling command exists on reset.",
      "language": "LTL_OVER_TYPED_SCAN_PREDICATES",
      "encoding_status": "NOT_LOWERED_TO_MODEL_CHECKER",
      "scope": "SCAN_SEQUENCE"
    }
  ]
}

ARCHITECTURAL PLAN:
{
  "state_machine": [
    {
      "state": "STOPPED",
      "meaning": "Fill command is false; includes initial/reset, safety stop, high-level stop, inhibit, and middle-band retain-off.",
      "outputs": {
        "Fill": false
      },
      "transitions": [
        {
          "to": "STOPPED",
          "guard": "SensorFault OR Inhibit OR HighWet",
          "action": "force Fill := FALSE; remain stopped"
        },
        {
          "to": "FILLING",
          "guard": "NOT SensorFault AND NOT Inhibit AND NOT HighWet AND NOT LowWet",
          "action": "start fill; Fill := TRUE"
        },
        {
          "to": "STOPPED",
          "guard": "otherwise, including LowWet AND NOT HighWet AND NOT Inhibit (middle band)",
          "action": "retain Fill := FALSE"
        }
      ]
    },
    {
      "state": "FILLING",
      "meaning": "Fill command is true; active refill unless stopped by safety/operational priority.",
      "outputs": {
        "Fill": true
      },
      "transitions": [
        {
          "to": "STOPPED",
          "guard": "SensorFault OR Inhibit OR HighWet",
          "action": "force Fill := FALSE; stop fill"
        },
        {
          "to": "FILLING",
          "guard": "NOT SensorFault AND NOT Inhibit AND NOT HighWet AND NOT LowWet",
          "action": "continue fill; Fill := TRUE"
        },
        {
          "to": "FILLING",
          "guard": "LowWet AND NOT HighWet AND NOT Inhibit",
          "action": "retain Fill := TRUE in middle band"
        },
        {
          "to": "FILLING",
          "guard": "otherwise, with no stop condition and no low-dry start condition",
          "action": "retain Fill := TRUE"
        }
      ]
    }
  ],
  "timer_plan": {
    "required_timers": [],
    "pt_durations": {},
    "reset_conditions": [
      "No timers are used; hysteresis is state-based, not time-based.",
      "Instance reset clears FillState to STOPPED, Fill to FALSE, SensorFault to FALSE, and qFill to FALSE."
    ]
  },
  "priorities": [
    "1. Safety override: SensorFault = HighWet AND NOT LowWet is always derived and forces Fill = FALSE.",
    "2. Safety/operational override: Inhibit = TRUE forces Fill = FALSE.",
    "3. Safety override: HighWet = TRUE forces Fill = FALSE.",
    "4. Start request: if not stopped and LowWet = FALSE, Fill = TRUE.",
    "5. Hysteresis retain: in the middle band LowWet = TRUE AND HighWet = FALSE AND Inhibit = FALSE, retain previous Fill.",
    "6. Initial/reset default: Fill = FALSE and SensorFault = FALSE before the first scan and after reset."
  ],
  "initial_values": {
    "Fill": false,
    "SensorFault": false,
    "FillState": "STOPPED",
    "qFill": false,
    "SensorFaultNext": false
  },
  "scan_execution_order": [
    {
      "stage": 1,
      "name": "edge_sampling",
      "actions": [
        "Sample LowWet, HighWet, and Inhibit exactly once into scan-local values.",
        "Capture qFill from the previous observed O[k-1].Fill; at reset qFill = FALSE.",
        "No edge flags are required for this task; sampled BOOL values are used directly."
      ]
    },
    {
      "stage": 2,
      "name": "safety_reset_priority_and_state_transitions",
      "actions": [
        "Apply instance reset if present: FillState := STOPPED, Fill := FALSE, SensorFault := FALSE, qFill := FALSE.",
        "Compute SensorFaultNext := HighWet AND NOT LowWet.",
        "Evaluate stop priority first: if SensorFaultNext OR Inhibit OR HighWet, next state is STOPPED and Fill is forced FALSE.",
        "Else evaluate start: if NOT LowWet AND NOT HighWet AND NOT Inhibit, next state is FILLING.",
        "Else retain the current FillState for middle-band hysteresis."
      ]
    },
    {
      "stage": 3,
      "name": "unconditional_timer_fb_calls_outside_case_if",
      "actions": [
        "No timer function blocks are required.",
        "Stage intentionally contains no CASE/IF-gated timer calls; it is a no-op for this task."
      ]
    },
    {
      "stage": 4,
      "name": "unified_output_assignments",
      "actions": [
        "SensorFault := SensorFaultNext.",
        "Fill := (FillState = FILLING).",
        "qFill := Fill, so qFill for the next scan equals the actual post-scan observed O[k].Fill."
      ]
    }
  ],
  "formal_assertions": [
    {
      "id": "A1",
      "formula": "G(SensorFault <-> (HighWet & !LowWet))"
    },
    {
      "id": "A2",
      "formula": "G((SensorFault | Inhibit | HighWet) -> !Fill)"
    },
    {
      "id": "A3",
      "formula": "G((!LowWet & !HighWet & !Inhibit) -> Fill)"
    },
    {
      "id": "A4",
      "formula": "G((LowWet & !HighWet & !Inhibit) -> (Fill <-> Y Fill))"
    }
  ]
}

CODESYS DIALECT CARDS:
[
  {
    "id": "ton_timer",
    "title": "Standard IEC TON Timer Block Invocation",
    "body": "// Standard IEC TON timer: MUST invoke unconditionally OUTSIDE CASE/IF every scan!\nVAR\n    timer : TON;\n    runTimer : BOOL;\nEND_VAR\n// Control via boolean IN flag (never put timer(...) only inside an IF/CASE arm):\nrunTimer := (state = 1) AND NOT resetCmd;\ntimer(IN := runTimer, PT := T#2s);\nIF timer.Q THEN\n    // Timer expired; timer.ET holds elapsed time\nEND_IF;"
  }
]
